import React, { useState } from 'react';

type Page = 'scan' | 'login' | 'booking' | 'payment' | 'confirmation';

interface BookingData {
  name: string;
  mobile: string;
  checkinDate: string;
  checkoutDate: string;
  paymentAmount: number;
  paymentType: 'advance' | 'full' | 'custom';
  totalAmount: number;
  customAmount: number;
}

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('scan');
  const [bookingData, setBookingData] = useState<BookingData>({
    name: '',
    mobile: '',
    checkinDate: '',
    checkoutDate: '',
    paymentAmount: 1000,
    paymentType: 'advance',
    totalAmount: 3500,
    customAmount: 1000
  });

  const renderPage = () => {
    switch (currentPage) {
      case 'scan':
        return <QRScanPage onScanSuccess={() => setCurrentPage('login')} />;
      case 'login':
        return <LoginPage 
          bookingData={bookingData}
          setBookingData={setBookingData}
          onNext={() => setCurrentPage('booking')} 
          onBack={() => setCurrentPage('scan')} 
        />;
      case 'booking':
        return (
          <BookingPage 
            bookingData={bookingData}
            setBookingData={setBookingData}
            onNext={() => setCurrentPage('payment')}
            onBack={() => setCurrentPage('login')}
          />
        );
      case 'payment':
        return (
          <PaymentPage 
            amount={bookingData.paymentAmount}
            onSuccess={() => setCurrentPage('confirmation')}
            onFail={() => setCurrentPage('booking')}
            onBack={() => setCurrentPage('booking')}
          />
        );
      case 'confirmation':
        return <ConfirmationPage bookingData={bookingData} onNewBooking={() => {
          setCurrentPage('scan');
          setBookingData({ name: '', mobile: '', checkinDate: '', checkoutDate: '', paymentAmount: 1000, paymentType: 'advance', totalAmount: 3500, customAmount: 1000 });
        }} />;
      default:
        return <QRScanPage onScanSuccess={() => setCurrentPage('login')} />;
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      fontFamily: 'Arial, sans-serif'
    }}>
      {renderPage()}
    </div>
  );
};

// QR Scan Page
const QRScanPage: React.FC<{ onScanSuccess: () => void }> = ({ onScanSuccess }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [countdown, setCountdown] = useState(3);

  React.useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isScanning && countdown > 0) {
      interval = setInterval(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (isScanning && countdown === 0) {
      setTimeout(() => {
        onScanSuccess();
        setIsScanning(false);
        setCountdown(3);
      }, 1000);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isScanning, countdown, onScanSuccess]);

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        borderRadius: '20px',
        padding: '40px',
        maxWidth: '500px',
        width: '100%',
        textAlign: 'center',
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)'
      }}>
        <div style={{ fontSize: '4rem', marginBottom: '20px' }}>📱</div>
        <h1 style={{ color: '#333', marginBottom: '10px', fontSize: '2.5rem', fontWeight: '300' }}>
          QR Booking System
        </h1>
        <p style={{ color: '#666', marginBottom: '30px', fontSize: '1.1rem' }}>
          Scan QR code to start your booking
        </p>

        <div style={{
          border: '3px dashed #667eea',
          borderRadius: '15px',
          padding: '40px',
          marginBottom: '30px',
          minHeight: '200px',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          background: isScanning ? '#f0f8ff' : '#fafafa'
        }}>
          {isScanning ? (
            <>
              <div style={{ 
                fontSize: '3rem', 
                marginBottom: '20px',
                animation: 'pulse 1s infinite'
              }}>📷</div>
              <h3 style={{ color: '#667eea', margin: '0 0 10px 0' }}>Scanning QR Code...</h3>
              {countdown > 0 ? (
                <p style={{ color: '#666', margin: 0 }}>Detecting in {countdown}s</p>
              ) : (
                <p style={{ color: '#4CAF50', margin: 0 }}>✅ QR Code Found!</p>
              )}
            </>
          ) : (
            <>
              <div style={{ fontSize: '3rem', marginBottom: '20px', opacity: 0.5 }}>📷</div>
              <h3 style={{ color: '#666', margin: '0 0 10px 0' }}>Camera Ready</h3>
              <p style={{ color: '#999', margin: 0 }}>Click "Start Scanning" to begin</p>
            </>
          )}
        </div>

        {!isScanning ? (
          <button
            onClick={() => setIsScanning(true)}
            style={{
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '25px',
              padding: '15px 40px',
              fontSize: '1.1rem',
              fontWeight: '600',
              cursor: 'pointer',
              transition: 'transform 0.2s ease',
              boxShadow: '0 5px 15px rgba(102, 126, 234, 0.3)'
            }}
            onMouseOver={(e) => e.currentTarget.style.transform = 'translateY(-2px)'}
            onMouseOut={(e) => e.currentTarget.style.transform = 'translateY(0)'}
          >
            🎯 Start Scanning
          </button>
        ) : (
          <button
            onClick={() => {
              setIsScanning(false);
              setCountdown(3);
            }}
            style={{
              background: '#ff4757',
              color: 'white',
              border: 'none',
              borderRadius: '25px',
              padding: '15px 40px',
              fontSize: '1.1rem',
              fontWeight: '600',
              cursor: 'pointer'
            }}
          >
            ⏹ Stop Scanning
          </button>
        )}

        <div style={{ marginTop: '30px', padding: '15px', background: '#e8f4fd', borderRadius: '10px' }}>
          <p style={{ color: '#1e88e5', margin: 0, fontSize: '0.9rem' }}>
            💡 <strong>Demo Mode:</strong> This will simulate QR code scanning for testing
          </p>
        </div>
      </div>
    </div>
  );
};

// Login/Register Page
const LoginPage: React.FC<{ 
  bookingData: BookingData;
  setBookingData: (data: BookingData) => void;
  onNext: () => void; 
  onBack: () => void;
}> = ({ bookingData, setBookingData, onNext, onBack }) => {

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (bookingData.name.trim() && bookingData.mobile.trim()) {
      onNext();
    } else {
      alert('Please fill in all fields');
    }
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        borderRadius: '20px',
        padding: '40px',
        maxWidth: '450px',
        width: '100%',
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)'
      }}>
        <button
          onClick={onBack}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.5rem',
            cursor: 'pointer',
            marginBottom: '20px',
            color: '#667eea'
          }}
        >
          ← Back
        </button>

        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <div style={{ fontSize: '3rem', marginBottom: '15px' }}>👤</div>
          <h2 style={{ color: '#333', margin: '0 0 10px 0', fontSize: '2rem', fontWeight: '300' }}>
            Customer Details
          </h2>
          <p style={{ color: '#666', margin: 0 }}>Enter your information to continue</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              👤 Full Name
            </label>
            <input
              type="text"
              value={bookingData.name}
              onChange={(e) => setBookingData({ ...bookingData, name: e.target.value })}
              placeholder="Enter your full name"
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                transition: 'border-color 0.3s ease',
                boxSizing: 'border-box'
              }}
              onFocus={(e) => e.target.style.borderColor = '#667eea'}
              onBlur={(e) => e.target.style.borderColor = '#e1e8ed'}
              required
            />
          </div>

          <div style={{ marginBottom: '30px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              📱 Mobile Number
            </label>
            <input
              type="tel"
              value={bookingData.mobile}
              onChange={(e) => setBookingData({ ...bookingData, mobile: e.target.value })}
              placeholder="Enter your mobile number"
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                transition: 'border-color 0.3s ease',
                boxSizing: 'border-box'
              }}
              onFocus={(e) => e.target.style.borderColor = '#667eea'}
              onBlur={(e) => e.target.style.borderColor = '#e1e8ed'}
              required
            />
          </div>

          <button
            type="submit"
            style={{
              width: '100%',
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '15px',
              padding: '18px',
              fontSize: '1.1rem',
              fontWeight: '600',
              cursor: 'pointer',
              transition: 'transform 0.2s ease',
              boxShadow: '0 5px 15px rgba(102, 126, 234, 0.3)'
            }}
            onMouseOver={(e) => e.currentTarget.style.transform = 'translateY(-2px)'}
            onMouseOut={(e) => e.currentTarget.style.transform = 'translateY(0)'}
          >
            Continue to Booking →
          </button>
        </form>
      </div>
    </div>
  );
};

// Booking Page
const BookingPage: React.FC<{
  bookingData: BookingData;
  setBookingData: (data: BookingData) => void;
  onNext: () => void;
  onBack: () => void;
}> = ({ bookingData, setBookingData, onNext, onBack }) => {

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (bookingData.checkinDate && bookingData.checkoutDate) {
      if (new Date(bookingData.checkinDate) >= new Date(bookingData.checkoutDate)) {
        alert('Check-out date must be after check-in date');
        return;
      }
      onNext();
    } else {
      alert('Please select both check-in and check-out dates');
    }
  };

  // Generate available dates (next 30 days)
  const getAvailableDates = () => {
    const dates = [];
    const today = new Date();
    for (let i = 0; i < 30; i++) {
      const date = new Date(today);
      date.setDate(today.getDate() + i);
      dates.push(date.toISOString().split('T')[0]);
    }
    return dates;
  };

  const availableDates = getAvailableDates();

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '20px'
    }}>
      <div style={{
        background: 'rgba(255, 255, 255, 0.95)',
        borderRadius: '20px',
        padding: '40px',
        maxWidth: '500px',
        width: '100%',
        boxShadow: '0 20px 40px rgba(0,0,0,0.1)'
      }}>
        <button
          onClick={onBack}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.5rem',
            cursor: 'pointer',
            marginBottom: '20px',
            color: '#667eea'
          }}
        >
          ← Back
        </button>

        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <div style={{ fontSize: '3rem', marginBottom: '15px' }}>📅</div>
          <h2 style={{ color: '#333', margin: '0 0 10px 0', fontSize: '2rem', fontWeight: '300' }}>
            Booking Details
          </h2>
          <p style={{ color: '#666', margin: 0 }}>Select your check-in and check-out dates</p>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              📅 Check-in Date
            </label>
            <select
              value={bookingData.checkinDate}
              onChange={(e) => setBookingData({ ...bookingData, checkinDate: e.target.value })}
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                boxSizing: 'border-box',
                background: 'white'
              }}
              required
            >
              <option value="">Select check-in date</option>
              {availableDates.map(date => (
                <option key={date} value={date}>
                  {new Date(date).toLocaleDateString('en-US', { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}
                </option>
              ))}
            </select>
          </div>

          <div style={{ marginBottom: '20px' }}>
            <label style={{ 
              display: 'block', 
              marginBottom: '8px', 
              color: '#333', 
              fontWeight: '500' 
            }}>
              📅 Check-out Date
            </label>
            <select
              value={bookingData.checkoutDate}
              onChange={(e) => setBookingData({ ...bookingData, checkoutDate: e.target.value })}
              style={{
                width: '100%',
                padding: '15px',
                border: '2px solid #e1e8ed',
                borderRadius: '10px',
                fontSize: '1rem',
                boxSizing: 'border-box',
                background: 'white'
              }}
              required
            >
              <option value="">Select check-out date</option>
              {availableDates.map(date => (
                <option key={date} value={date}>
                  {new Date(date).toLocaleDateString('en-US', { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric' 
                  })}
                </option>
              ))}
            </select>
          </div>

          <div style={{
            background: '#f8f9fa',
            padding: '20px',
            borderRadius: '10px',
            marginBottom: '30px',
            border: '1px solid #e9ecef'
          }}>
            <h3 style={{ margin: '0 0 20px 0', color: '#333', fontSize: '1.2rem' }}>💰 Payment Summary</h3>

            <div style={{ marginBottom: '20px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <span style={{ color: '#666' }}>Total Booking Amount:</span>
                <span style={{ fontWeight: 'bold', color: '#333', fontSize: '1.1rem' }}>₹{bookingData.totalAmount}</span>
              </div>
            </div>

            <div style={{ marginBottom: '20px' }}>
              <label style={{ display: 'block', marginBottom: '10px', color: '#333', fontWeight: '500' }}>
                💳 Payment Option:
              </label>

              <div style={{ marginBottom: '10px' }}>
                <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', padding: '10px', border: bookingData.paymentType === 'advance' ? '2px solid #667eea' : '2px solid #e1e8ed', borderRadius: '8px', marginBottom: '10px' }}>
                  <input
                    type="radio"
                    name="paymentType"
                    value="advance"
                    checked={bookingData.paymentType === 'advance'}
                    onChange={(e) => setBookingData({ ...bookingData, paymentType: 'advance', paymentAmount: 1000 })}
                    style={{ marginRight: '10px' }}
                  />
                  <div>
                    <div style={{ fontWeight: '600', color: '#333' }}>Advance Payment - ₹1000</div>
                    <div style={{ fontSize: '0.9rem', color: '#666' }}>Pay minimum advance now, rest at check-in</div>
                  </div>
                </label>
              </div>

              <div style={{ marginBottom: '10px' }}>
                <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', padding: '10px', border: bookingData.paymentType === 'full' ? '2px solid #667eea' : '2px solid #e1e8ed', borderRadius: '8px', marginBottom: '10px' }}>
                  <input
                    type="radio"
                    name="paymentType"
                    value="full"
                    checked={bookingData.paymentType === 'full'}
                    onChange={(e) => setBookingData({ ...bookingData, paymentType: 'full', paymentAmount: bookingData.totalAmount })}
                    style={{ marginRight: '10px' }}
                  />
                  <div>
                    <div style={{ fontWeight: '600', color: '#333' }}>Full Payment - ₹{bookingData.totalAmount}</div>
                    <div style={{ fontSize: '0.9rem', color: '#666' }}>Pay complete amount now</div>
                  </div>
                </label>
              </div>

              <div>
                <label style={{ display: 'flex', alignItems: 'center', cursor: 'pointer', padding: '10px', border: bookingData.paymentType === 'custom' ? '2px solid #667eea' : '2px solid #e1e8ed', borderRadius: '8px' }}>
                  <input
                    type="radio"
                    name="paymentType"
                    value="custom"
                    checked={bookingData.paymentType === 'custom'}
                    onChange={(e) => setBookingData({ ...bookingData, paymentType: 'custom', paymentAmount: bookingData.customAmount })}
                    style={{ marginRight: '10px' }}
                  />
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: '600', color: '#333', marginBottom: '8px' }}>Custom Amount</div>
                    <div style={{ fontSize: '0.9rem', color: '#666', marginBottom: '10px' }}>Choose your payment amount (min ₹1000)</div>
                    <input
                      type="number"
                      min="1000"
                      max={bookingData.totalAmount}
                      value={bookingData.customAmount}
                      onChange={(e) => {
                        const amount = Math.max(1000, Math.min(bookingData.totalAmount, parseInt(e.target.value) || 1000));
                        setBookingData({ 
                          ...bookingData, 
                          customAmount: amount,
                          paymentAmount: bookingData.paymentType === 'custom' ? amount : bookingData.paymentAmount
                        });
                      }}
                      onFocus={() => setBookingData({ ...bookingData, paymentType: 'custom', paymentAmount: bookingData.customAmount })}
                      placeholder="Enter amount"
                      style={{
                        width: '120px',
                        padding: '8px 12px',
                        border: '1px solid #e1e8ed',
                        borderRadius: '6px',
                        fontSize: '0.9rem',
                        boxSizing: 'border-box'
                      }}
                    />
                  </div>
                </label>
              </div>
            </div>

            <div style={{ borderTop: '1px solid #e9ecef', paddingTop: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ color: '#666', fontSize: '1rem' }}>Amount to Pay Now:</span>
                <span style={{ fontWeight: 'bold', color: '#28a745', fontSize: '1.3rem' }}>₹{bookingData.paymentAmount}</span>
              </div>
              {(bookingData.paymentType === 'advance' || bookingData.paymentType === 'custom') && bookingData.paymentAmount < bookingData.totalAmount && (
                <p style={{ color: '#666', fontSize: '0.9rem', margin: '10px 0 0 0' }}>
                  ⚠️ Remaining ₹{bookingData.totalAmount - bookingData.paymentAmount} to be paid at check-in
                </p>
              )}
            </div>
          </div>

          <button
            type="submit"
            style={{
              width: '100%',
              background: 'linear-gradient(135deg, #28a745 0%, #20c997 100%)',
              color: 'white',
              border: 'none',
              borderRadius: '15px',
              padding: '18px',
              fontSize: '1.1rem',
              fontWeight: '600',
              cursor: 'pointer',
              transition: 'transform 0.2s ease',
              boxShadow: '0 5px 15px rgba(40, 167, 69, 0.3)'
            }}
            onMouseOver={(e) => e.currentTarget.style.transform = 'translateY(-2px)'}
            onMouseOut={(e) => e.currentTarget.style.transform = 'translateY(0)'}
          >
            Proceed to Payment →
          </button>
        </form>
      </div>
    </div>
  );
};

